import pathlib,tempfile,json,base64,subprocess,sys,hashlib
files={'retain-older-inputs.py': '', 'retention.test.py': '', 'archive-retention-plan.json': '', 'adversarial.test.py': ''}
with tempfile.TemporaryDirectory(prefix='keel-independent-retention-')as d:
 p=pathlib.Path(d)
 for n,b in files.items():(p/n).write_bytes(base64.b64decode(b))
 results=[]
 for n in ['retention.test.py','adversarial.test.py']:
  r=subprocess.run(['/usr/bin/python3',str(p/n)],capture_output=True,text=True,timeout=30);results.append({'file':n,'exitCode':r.returncode,'stdout':r.stdout,'stderr':r.stderr})
 print(json.dumps({'schema':'keel.independent-older-archive-linux-tests@1','operatorSHA256':hashlib.sha256((p/'retain-older-inputs.py').read_bytes()).hexdigest(),'platform':sys.platform,'tests':results,'temporaryRootRemovedOnExit':True,'productionActions':False}));exitcode=next((x['exitCode']for x in results if x['exitCode']),0)
sys.exit(exitcode)
